"""Closed isolated DATA-only byte replay of precisely the two requested probes."""
import argparse,hashlib,json,subprocess,sys
from pathlib import Path
assert sys.flags.isolated and sys.flags.dont_write_bytecode and sys.flags.no_site,'use-I-B-S'
S=Path(__file__).resolve().parent;sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
p=argparse.ArgumentParser()
for n in ['inventory','source-inventory','input','parameters','output-dir']:p.add_argument('--'+n,type=Path,required=True)
for n in ['inventory-sha256','source-inventory-sha256']:p.add_argument('--'+n,required=True)
a=p.parse_args();assert sha(a.inventory)==a.inventory_sha256 and sha(a.source_inventory)==a.source_inventory_sha256
i=json.loads(a.inventory.read_text());si=json.loads(a.source_inventory.read_text())
def closed():
 assert {f.name for f in S.iterdir()}==set(i['maintained_files']),'unlisted maintained directory entry'
 for n,e in i['maintained_files'].items():
  f=S/n;assert f.is_file() and not f.is_symlink() and sha(f)==e['sha256'] and f.stat().st_size==e['bytes'],'maintained identity mismatch: '+n
 assert sha(Path(__file__))==i['maintained_files'][Path(__file__).name]['sha256'],'executing recipe mismatch'
closed()
assert sha(a.input)==si['input_sha256'] and sha(a.parameters)==si['parameters_sha256']
assert not a.output_dir.exists(),'fresh replay path required';a.output_dir.mkdir(parents=True)
command=[sys.executable,'-I','-B','-S',str(S/'generate_probe.py'),'--inventory',str(a.inventory),'--inventory-sha256',a.inventory_sha256,'--input',str(a.input),'--parameters',str(a.parameters),'--output-dir',str(a.output_dir/'sources'),'--metadata-dir',str(a.output_dir/'metadata')]
closed();proc=subprocess.run(command,text=True,stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=60)
(a.output_dir/'generator.stdout.txt').write_text(proc.stdout);(a.output_dir/'generator.stderr.txt').write_text(proc.stderr);closed();assert proc.returncode==0,'generator refused; logs retained'
assert set(si['modules'])=={'TransferPoseidonCall14B0R00Data01','TransferPoseidonCall14B0R00Column1Probe01'}
assert {f.name for f in (a.output_dir/'sources').iterdir()}=={n+'.lean' for n in si['modules']}
for n,e in si['modules'].items():
 f=a.output_dir/'sources'/(n+'.lean');assert f.is_file() and not f.is_symlink() and sha(f)==e['sha256'] and f.stat().st_size==e['bytes'],'generated bytes differ: '+n
closed();result={'status':'passed','sources':2,'source_bytes':sum(e['bytes'] for e in si['modules'].values()),'kernel_runs':0,'proof_credit':0,'command':command,'generator_stdout_sha256':sha(a.output_dir/'generator.stdout.txt'),'generator_stderr_sha256':sha(a.output_dir/'generator.stderr.txt'),'maintained_inventory_sha256':sha(a.inventory),'source_inventory_sha256':sha(a.source_inventory),'executing_recipe_sha256':sha(Path(__file__)),'Python_version':sys.version,'scope':'DATA-only byte replay; requested two probes remain UNBUILT; remaining56sources NOT emitted'}
(a.output_dir/'replay-result01.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result))
